using System;using System.IO;using System.Linq;using System.Reflection;using System.Security.Cryptography;using System.Collections.Generic;
class InstallerChecks {
 static List<string> lines=new List<string>();static void Test(string name,bool yes){if(!yes)throw new Exception(name);lines.Add("PASS: "+name);}
 static int Main(string[] args){string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);try{
  var assembly=Assembly.LoadFrom(Path.GetFullPath(args[1]));var type=assembly.GetType("Installer");Action<string,object> field=(name,value)=>type.GetField(name,BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,value);Func<string,string> invoke=name=>(string)type.GetMethod(name,BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,null);
  string files=Path.Combine(root,"installed"),state=Path.Combine(files,"installation.txt"),desktop=Path.Combine(root,"desktop"),programs=Path.Combine(root,"programs");Directory.CreateDirectory(desktop);Directory.CreateDirectory(programs);field("Root",files);field("State",state);field("DesktopRoot",desktop);field("ProgramsRoot",programs);
  string current=invoke("Install");Test("installer writes versioned 5.1 payload",File.Exists(current)&&current.Contains("5.1.0"));Test("installer creates isolated Desktop and Start menu shortcuts",File.Exists(Path.Combine(desktop,"OpenAI Profiles.lnk"))&&File.Exists(Path.Combine(programs,"OpenAI Profiles","OpenAI Profiles.lnk")));
  bool unavailable=false;try{invoke("Rollback");}catch{unavailable=true;}Test("first installation has no fictional rollback",unavailable);
  string previous=Path.Combine(files,"versions","5.0.0","OpenAIProfiles.exe");Directory.CreateDirectory(Path.GetDirectoryName(previous));File.Copy(args[2],previous,true);File.WriteAllLines(state,new[]{"5.0.0",""});current=invoke("Install");var values=File.ReadAllLines(state);Test("upgrade records both active and previous release",values[0]=="5.1.0"&&values[1]=="5.0.0");Test("upgrade preserves previous executable",File.Exists(previous));
  string rolled=invoke("Rollback");Test("rollback selects previous executable",rolled==previous&&File.ReadAllLines(state)[0]=="5.0.0");string forward=invoke("Rollback");Test("rollback can return to retained newer release",forward==current&&File.ReadAllLines(state)[0]=="5.1.0");invoke("Install");Test("same-release reinstall retains rollback target",File.ReadAllLines(state)[1]=="5.0.0");
  using(var payload=assembly.GetManifestResourceStream("Launcher.exe"))using(var file=File.OpenRead(current))using(var hash=SHA256.Create())Test("installed bytes match embedded setup payload",hash.ComputeHash(payload).SequenceEqual(hash.ComputeHash(file)));
  Type shellType=Type.GetTypeFromProgID("WScript.Shell");dynamic shell=Activator.CreateInstance(shellType);dynamic shortcut=shell.CreateShortcut(Path.Combine(desktop,"OpenAI Profiles.lnk"));Test("installed shortcut opens selected active release",String.Equals((string)shortcut.TargetPath,current,StringComparison.OrdinalIgnoreCase));System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shortcut);System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shell);
  Test("installer state commits retain prior metadata backup",File.Exists(state+".bak"));return 0;
 }catch(Exception e){lines.Add(e.ToString());return 1;}finally{File.WriteAllLines(Path.Combine(root,"installer-results.txt"),lines);foreach(string line in lines)Console.WriteLine(line);}}
}
